class EllipsisWebhooksDeliveries {
  constructor(private readonly transport: Transport) {
  }

  /**
   * Get Webhook Delivery
   *
   * Inspect a delivery's payload and attempts.
   *
   * Payloads are immutable across retries. Attempt details include HTTP
   * status, timing, and errors. Response bodies are not retained.
   *
   * Required permissions: read:webhooks.
   * API key: Supported.
   * CLI user token: Supported.
   * Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
   * Higher permission levels include lower levels: read < write < delete.
   */
  async get(delivery_id: string): Promise<S['WebhookDeliveryResponse']> {
    const path = `/v1/webhooks/deliveries/${enc(delivery_id)}`;
    return await this.transport.request<S['WebhookDeliveryResponse']>('GET', path);
  }

  /**
   * List Webhook Deliveries
   *
   * List webhook deliveries, newest first.
   *
   * Includes verification pings and deliveries for deleted webhooks.
   * History is retained for 30 days. Retries belong to the same delivery.
   *
   * Required permissions: read:webhooks.
   * API key: Supported.
   * CLI user token: Supported.
   * Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
   * Higher permission levels include lower levels: read < write < delete.
   */
  async list(options: { webhook_id?: string | null; event_type?: S['WebhookEventType'] | null; status?: S['WebhookDeliveryStatus'] | null; start?: string | null; end?: string | null; limit?: number; cursor?: string | null } = {}): Promise<Page<S['WebhookDelivery'], S['WebhookDeliveriesListResponse']>> {
    const path = '/v1/webhooks/deliveries';
    const query = buildQuery({ webhook_id: options.webhook_id, event_type: options.event_type, status: options.status, start: options.start, end: options.end, limit: options.limit, cursor: options.cursor });
    const response = await this.transport.request<S['WebhookDeliveriesListResponse']>('GET', path, { query });
    return new Page(response, 'deliveries', (cursor) =>
      this.list({ ...options, cursor })
    );
  }
}

class EllipsisWebhooks {
  readonly deliveries: EllipsisWebhooksDeliveries;
  constructor(private readonly transport: Transport) {
    this.deliveries = new EllipsisWebhooksDeliveries(transport);
  }

  /**
   * Create Webhook
   *
   * Create a webhook and send a verification ping.
   *
   * Save the signing secret from this response; it is returned once.
   * Accounts default to three webhook slots, including unverified and
   * pending ones; your account may have a custom allowance. A ping returning HTTP 200 moves unverified to pending. Contact
   * Ellipsis to activate it and receive session.create events.
   *
   * Required permissions: write:webhooks.
   * API key: Supported.
   * CLI user token: Supported.
   * Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
   * Higher permission levels include lower levels: read < write < delete.
   */
  async create(options: { description?: string | null; events: ("session.create")[]; url: string }): Promise<S['CreateWebhookResponse']> {
    const path = '/v1/webhooks';
    const body = buildBody({ description: options.description, events: options.events, url: options.url });
    return await this.transport.request<S['CreateWebhookResponse']>('POST', path, { body });
  }

  /**
   * Delete Webhook
   *
   * Delete a webhook and cancel outstanding deliveries.
   *
   * An HTTP request already in flight may finish. Delivery history remains
   * available for 30 days. Deletion frees a webhook slot.
   *
   * Required permissions: delete:webhooks.
   * API key: Supported.
   * CLI user token: Supported.
   * Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
   * Higher permission levels include lower levels: read < write < delete.
   */
  async delete(webhook_id: string): Promise<void> {
    const path = `/v1/webhooks/${enc(webhook_id)}`;
    await this.transport.request<void>('DELETE', path);
  }

  /**
   * Get Webhook
   *
   * Get a webhook's configuration and approval state.
   *
   * Required permissions: read:webhooks.
   * API key: Supported.
   * CLI user token: Supported.
   * Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
   * Higher permission levels include lower levels: read < write < delete.
   */
  async get(webhook_id: string): Promise<S['WebhookResponse']> {
    const path = `/v1/webhooks/${enc(webhook_id)}`;
    return await this.transport.request<S['WebhookResponse']>('GET', path);
  }

  /**
   * List Webhooks
   *
   * List your webhooks and their delivery summaries.
   *
   * Required permissions: read:webhooks.
   * API key: Supported.
   * CLI user token: Supported.
   * Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
   * Higher permission levels include lower levels: read < write < delete.
   */
  async list(): Promise<S['WebhooksListResponse']> {
    const path = '/v1/webhooks';
    return await this.transport.request<S['WebhooksListResponse']>('GET', path);
  }

  /**
   * Ping Webhook
   *
   * Send a signed verification or test ping.
   *
   * Available in every state. Only HTTP 200 verifies a destination;
   * successful pings never activate it. The default limit is five pings per
   * account per minute, including creation and URL changes. Custom
   * account allowances apply.
   *
   * Required permissions: write:webhooks.
   * API key: Supported.
   * CLI user token: Supported.
   * Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
   * Higher permission levels include lower levels: read < write < delete.
   */
  async ping(webhook_id: string): Promise<void> {
    const path = `/v1/webhooks/${enc(webhook_id)}/ping`;
    await this.transport.request<void>('POST', path);
  }

  /**
   * Update Webhook
   *
   * Replace a webhook's configuration.
   *
   * Changing the URL cancels outstanding deliveries, clears verification
   * and approval, and sends another ping. State and signing secret cannot
   * be set here. Updating description or subscriptions preserves approval.
   *
   * Required permissions: write:webhooks.
   * API key: Supported.
   * CLI user token: Supported.
   * Sandbox token: Not supported by sandbox tokens, even with permissions.ellipsis enabled.
   * Higher permission levels include lower levels: read < write < delete.
   */
  async update(webhook_id: string, options: { description?: string | null; events: ("session.create")[]; url: string }): Promise<S['WebhookResponse']> {
    const path = `/v1/webhooks/${enc(webhook_id)}`;
    const body = buildBody({ description: options.description, events: options.events, url: options.url });
    return await this.transport.request<S['WebhookResponse']>('PUT', path, { body });
  }
}

